import sys

def check_records(test_cases):
    results = []
    for n, p_c_pairs in test_cases:
        p_prev, c_prev = 0, 0
        for p, c in p_c_pairs:
            if p < p_prev or c > c_prev or c < c_prev:
                results.append("NO")
                break
            p_prev, c_prev = p, c
        else:
            results.append("YES")
    return results

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    t_index = 0
    results = []
    while t_index < len(data):
        n = int(data[t_index])
        t_index += 1
        p_c_pairs = [(int(data[t_index]), int(data[t_index + 1])) for _ in range(n)]
        t_index += 2
        results.extend(check_records([(n, p_c_pairs)]))

    for result in results:
        print(result)

def is_valid_sequence(n, stats):
    for i in range(1, n):
        if stats[i][1] < stats[i-1][1]:
            return False
        if stats[i][0] < stats[i-1][0] and stats[i][1] > stats[i-1][1]:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []
    for _ in range(t):
        n = int(data[index])
        index += 1
        stats = []
        for _ in range(n):
            p = int(data[index])
            c = int(data[index + 1])
            stats.append((p, c))
            index += 2
        results.append("YES" if is_valid_sequence(n, stats) else "NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
